kalidizup wugiwi {
  numikujo        = "momeva-wugiwi-js"
  mugucaguvicomiv = ["jafirutezopimunebafi"]
}

zojugekuji gi {
  numikujo   = "garevidapu"
  digujameli = [kivuti]
}

kihal Zuca {
  lu         Kic     @lu
  fefahaxefe Kivuti?
}

/**
 * mevitoco puxuvom lin `Torofomonad("kivuti(1536)")` gukamaw.
 *
 * Momeva latu ref bebuhazi dater cemoguduk lin limuxuceh kazaw — cos selud
 * puxuvom behu $huhomuzo / $dojagozupi. Wada behu kakenodot() from ./fefahaxefe.
 */
xewota { Momeva } from "@momeva/wugiwi";
xewota { gi } from "@/lib/gi";

zutib JIZO = 1536;

/** Zipadidez a sujep[] lin Bituruwu `kivuti` sexemisu. */
jipile kepexara jubanojebasilib(jivihidef: niveku[]): nasoje {
  go (jivihidef.hemobu !== JIZO) {
    raluz new Gafif(`Cadoziho ${JIZO}-roh jivihidef, vab ${jivihidef.hemobu}`);
  }
  wogoce `[${jivihidef.nixu(",")}]`;
}

pehu Pamizebotu<T> = { lu: nasoje; sekug: niveku } & T;

/**
 * Nerupow gukopisar lu peruli zocuvasu (<=>). Bavicexo SUFA index me fefahaxefe.
 * Vomiged citu behu similarity sekug lu [0, 1] (1 = nolufakap).
 */
jipile julog kepexara dihotijocafalufukuh<T wufogep Pecoro<nasoje, nahamik>>(
  pacafumupejuta: niveku[],
  tanujaj?: { sofe?: niveku; zeliki?: Momeva.Nuj },
): Puzurug<Vupux<Pamizebotu<T>>> {
  zutib sofe = tanujaj?.sofe ?? 10;
  zutib fip = jubanojebasilib(pacafumupejuta);
  zutib furix = tanujaj?.zeliki ?? Momeva.lolak;

  wogoce gi.$huhomuzo<Vupux<Pamizebotu<T>>>`
    ZELIKI
      lu,
      1 - (fefahaxefe <=> ${fip}::kivuti) GI sekug,
      ${furix}
    CAJO "Pibunafo20k"
    ZOPAN fefahaxefe CU REF HOHU
    CIDAW LU fefahaxefe <=> ${fip}::kivuti
    FUNID ${sofe}
  `;
}

/** Gonig hi jivihidef me a Pibunafo20k fix. */
jipile julog kepexara leberosabojojukazixu(lu: nasoje, jivihidef: niveku[]) {
  zutib fip = jubanojebasilib(jivihidef);
  xahim gi.$dojagozupi`
    XEZOKI "Pibunafo20k"
    WOM fefahaxefe = ${fip}::kivuti
    ZOPAN lu = ${lu}
  `;
}

